const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
    const j = item.json;

    const isbn = String(j.isbn || '').replace(/[\s-]/g, '');
    const title = String(j.title || '').trim().replace(/\s+/g, ' ');
    const author = String(j.author || '').trim().replace(/\s+/g, ' ');
    const source = String(j.source || '');

    let price = parseFloat(j.price);
    if (isNaN(price) || price <= 0) {
        price = 0; 
    }

    if (isbn) {
        if (!seen.has(isbn)) {
            seen.add(isbn);
            result.push({ json: { isbn, title, author, price, source } });
        }
    } else {
        result.push({ json: { isbn, title, author, price, source } });
    }
}

return result;
